"use strict";(self.webpackChunkmy_personal_website=self.webpackChunkmy_personal_website||[]).push([[3696],{1790:(e,t,n)=>{n.d(t,{A:()=>a});const a=n.p+"assets/images/20260823_182053-efe0d07f67efc52b90643358b9932588.jpg"},3632:e=>{e.exports=JSON.parse('{"permalink":"/blog/handwriting-blogs","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-08-25-handwriting-blogs/index.md","source":"@site/blog/2026-08-25-handwriting-blogs/index.md","title":"Handwriting Blogs","description":"I\'m at a library in Missouri writing this. I\'m going to start writing these on paper first before I type it out. I was listening to a podcast yesterday that said physically writing things down is more engaging and creative for your brain. They said it had something to do with your hand muscles being activated, which creates a more hand-on experience (No pun intended). I\'m not sure why, but it feels like my hand-writing has improved. It\'s strange because I haven\'t written this much since college.","date":"2026-08-25T00:00:00.000Z","tags":[{"inline":true,"label":"Travel","permalink":"/blog/tags/travel"}],"readingTime":2.4,"hasTruncateMarker":false,"authors":[{"name":"Travis Blanks","title":"Jack of All Trades","url":"https://travisblanks.com","imageURL":"/img/channels4_profile.jpg","key":"Gekaku","page":null}],"frontMatter":{"slug":"handwriting-blogs","title":"Handwriting Blogs","authors":"Gekaku","tags":["Travel"]},"unlisted":false,"nextItem":{"title":"Starting Over","permalink":"/blog/starting-over"}}')},4132:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>d,frontMatter:()=>s,metadata:()=>a,toc:()=>l});var a=n(3632),o=n(4848),i=n(8453);const s={slug:"handwriting-blogs",title:"Handwriting Blogs",authors:"Gekaku",tags:["Travel"]},r=void 0,h={authorsImageUrls:[void 0]},l=[];function c(e){const t={a:"a",img:"img",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:"I'm at a library in Missouri writing this. I'm going to start writing these on paper first before I type it out. I was listening to a podcast yesterday that said physically writing things down is more engaging and creative for your brain. They said it had something to do with your hand muscles being activated, which creates a more hand-on experience (No pun intended). I'm not sure why, but it feels like my hand-writing has improved. It's strange because I haven't written this much since college."}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{alt:"Here&#39;s a photo of the paper I used to write this",src:n(4752).A+"",width:"4032",height:"2268"})}),"\n",(0,o.jsxs)(t.p,{children:["I'm on my way home from an anime convention called Anime Magic in Rosemont, Illinois. I was selling ",(0,o.jsx)(t.a,{href:"https://rectanglecorner.com/",children:"Rectangle Corner"})," controllers there. Out of the three anime conventions I've sold merch at, this was the best one by far. Not only was the foot traffic greater, the attraction to my booth was higher. I took my co-owner's advice and tried playing the game that I have at the booth for people to test out the controllers. He thought it would attract more people to the booth. Since my back was turned away from the passer-bys, I'm not sure how effective that was. I was told by another vendor that this convention had 8-10 thousand attendees, so it may have been a combination of the size and my new strategy. They actually let me drive my car into the convention center to set up and break down."]}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{alt:"Here&#39;s a photo of my booth and my car. I was in the process of breaking down",src:n(1790).A+"",width:"4032",height:"2268"})}),"\n",(0,o.jsx)(t.p,{children:"This is the second convention I've been to sine leaving Texas for my first one two weeks ago. I'm really lucky I got to do this. I spent hours working on the used car I recently bought to get it ready for this trip. After all that work, I still had to work on it a bit more while on the road. Turns out I didn't fully close a valve cover gasket. Halfway through the trip, I noticed oil was spilling in large amounts. I was able to alleviate it a bit, but there is still white smoke and the smell of burning engine oil when I check under the hood."}),"\n",(0,o.jsx)(t.p,{children:"Fixing cars isn't for the weak of heart. It feels like another problem arises right after I fix an issue. I cried for the first time in years when I thought my car was fixed, only to find out my power steering hose was broken and pouring fluid everywhere. This happened on my first attempt to leave for my trip. I cut it close, but I'm glad I was able to do this. I learned a lot about my car, as well as how far I can push myself to figure out solutions in dire situations."})]})}function d(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},4752:(e,t,n)=>{n.d(t,{A:()=>a});const a=n.p+"assets/images/20260825_112553-4aa2a1d1a841c9d99921cbb0be46bbfa.jpg"},8453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var a=n(6540);const o={},i=a.createContext(o);function s(e){const t=a.useContext(i);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);